begin;

create table if not exists public.client_documents (
  id uuid primary key default gen_random_uuid(),
  client_id uuid references public.clients(id) on delete set null,
  parent_document_id uuid references public.client_documents(id) on delete set null,
  record_type text not null default 'contract',
  doc_type text not null,
  doc_type_label text not null,
  doc_date date,
  document_number text,
  agreement_number text,
  parent_contract_number text,
  parent_contract_date date,
  client_name text not null default '',
  client_inn text,
  price text,
  tax_system text,
  tax_rate text,
  employees text,
  client_signer text,
  client_signer_title text,
  payment_period text,
  start_date date,
  end_date date,
  new_price text,
  new_price_date date,
  reason text,
  special_terms text,
  status text not null default 'действует',
  source text,
  source_file text,
  source_text text,
  client_snapshot jsonb not null default '{}'::jsonb,
  form_data jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  created_by uuid references auth.users(id) on delete set null,
  updated_by uuid references auth.users(id) on delete set null,
  constraint client_documents_record_type_check
    check (record_type in ('contract', 'related')),
  constraint client_documents_doc_type_not_blank
    check (length(btrim(doc_type)) > 0),
  constraint client_documents_doc_type_label_not_blank
    check (length(btrim(doc_type_label)) > 0)
);

create index if not exists client_documents_client_id_idx
  on public.client_documents (client_id, doc_date desc, created_at desc);

create index if not exists client_documents_parent_document_id_idx
  on public.client_documents (parent_document_id);

create index if not exists client_documents_record_type_idx
  on public.client_documents (record_type, doc_date desc);

create index if not exists client_documents_inn_idx
  on public.client_documents (client_inn);


