insert into public.client_documents (
  client_id,
  record_type,
  doc_type,
  doc_type_label,
  doc_date,
  document_number,
  agreement_number,
  parent_contract_number,
  parent_contract_date,
  client_name,
  client_inn,
  price,
  tax_system,
  tax_rate,
  employees,
  client_signer,
  client_signer_title,
  payment_period,
  start_date,
  end_date,
  new_price,
  new_price_date,
  reason,
  special_terms,
  status,
  source,
  source_file,
  client_snapshot,
  form_data
)
select
  matched_client.id,
  item->>'recordType',
  item->>'docType',
  item->>'docTypeLabel',
  case
    when coalesce(item->>'docDate', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      then (item->>'docDate')::date
  end,
  nullif(item->>'contractNumber', ''),
  nullif(item->>'agreementNumber', ''),
  nullif(item->>'parentContractNumber', ''),
  case
    when coalesce(item->>'parentContractDate', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      then (item->>'parentContractDate')::date
  end,
  item->>'clientName',
  nullif(item->>'inn', ''),
  nullif(item->>'price', ''),
  nullif(item->>'taxSystem', ''),
  nullif(item->>'taxRate', ''),
  nullif(item->>'employees', ''),
  nullif(item->>'clientSigner', ''),
  nullif(item->>'clientSignerTitle', ''),
  nullif(item->>'paymentPeriod', ''),
  case
    when coalesce(item->>'startDate', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      then (item->>'startDate')::date
  end,
  case
    when coalesce(item->>'endDate', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      then (item->>'endDate')::date
  end,
  nullif(item->>'newPrice', ''),
  case
    when coalesce(item->>'newPriceDate', '') ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
      then (item->>'newPriceDate')::date
  end,
  nullif(item->>'reason', ''),
  nullif(item->>'specialTerms', ''),
  coalesce(nullif(item->>'status', ''), 'действует'),
  nullif(item->>'source', ''),
  nullif(item->>'sourceFile', ''),
  coalesce(item->'formData', '{}'::jsonb),
  coalesce(item->'formData', '{}'::jsonb)
from legacy_rows
left join lateral (
  select clients.id
  from public.clients
  where regexp_replace(coalesce(clients.inn, ''), '[^0-9]', '', 'g') =
        regexp_replace(coalesce(legacy_rows.item->>'inn', ''), '[^0-9]', '', 'g')
    and regexp_replace(coalesce(legacy_rows.item->>'inn', ''), '[^0-9]', '', 'g') <> ''
  limit 1
) as matched_client on true
where not exists (
  select 1
  from public.client_documents existing
  where coalesce(existing.document_number, '') = coalesce(legacy_rows.item->>'contractNumber', '')
    and existing.client_name = coalesce(legacy_rows.item->>'clientName', '')
    and existing.doc_type_label = coalesce(legacy_rows.item->>'docTypeLabel', '')
);

update public.client_documents related
set parent_document_id = parent.id
from public.client_documents parent
where related.record_type = 'related'
  and related.parent_document_id is null
  and parent.record_type = 'contract'
  and regexp_replace(
        coalesce(substring(related.parent_contract_number from '([0-9]{1,4}[[:space:]]*/[[:space:]]*[0-9]{1,2})'), ''),
        '[[:space:]]', '', 'g'
      ) = regexp_replace(
        coalesce(substring(parent.document_number from '([0-9]{1,4}[[:space:]]*/[[:space:]]*[0-9]{1,2})'), ''),
        '[[:space:]]', '', 'g'
      )
  and (
    related.client_id = parent.client_id
    or (
      related.client_id is null
      and parent.client_id is null
      and coalesce(related.client_inn, '') = coalesce(parent.client_inn, '')
    )
  );

alter table public.client_documents enable row level security;

drop policy if exists "Authenticated users can read client documents"
  on public.client_documents;
create policy "Authenticated users can read client documents"
  on public.client_documents
  for select
  to authenticated
  using (true);

drop policy if exists "Authenticated users can create client documents"
  on public.client_documents;
create policy "Authenticated users can create client documents"
  on public.client_documents
  for insert
  to authenticated
  with check (auth.uid() = created_by);

drop policy if exists "Authenticated users can update client documents"
  on public.client_documents;
create policy "Authenticated users can update client documents"
  on public.client_documents
  for update
  to authenticated
  using (true)
  with check (auth.uid() = updated_by);

drop policy if exists "Authenticated users can delete client documents"
  on public.client_documents;
create policy "Authenticated users can delete client documents"
  on public.client_documents
  for delete
  to authenticated
  using (true);

grant select, insert, update, delete
  on public.client_documents
  to authenticated;

comment on table public.client_documents is
  'Договоры, дополнительные соглашения и их журнал с привязкой к карточкам клиентов.';

comment on column public.client_documents.client_snapshot is
  'Снимок реквизитов клиента на момент создания документа.';

commit;
